"""Tests for the Switch/case helper."""

from jc.parsers.pbPlist.Switch import Switch


def collected_cases(value, case_values):
    matched = []
    for case in Switch(value):
        for case_value in case_values:
            if case(case_value):
                matched.append(case_value)
    return matched


def test_initial_state():
    switch = Switch('value')

    assert switch.value == 'value'
    assert switch.fall is False


def test_iterator_yields_only_the_match_method():
    switch = Switch('a')
    iterator = iter(switch)

    assert next(iterator) == switch.match
    with pytest_raises_stop_iteration():
        next(iterator)


class pytest_raises_stop_iteration:
    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        assert exc_type is StopIteration
        return True


def test_matches_the_single_corresponding_case():
    assert collected_cases('b', ['a', 'b', 'c']) == ['b']


def test_no_match_returns_false_for_every_case():
    assert collected_cases('z', ['a', 'b', 'c']) == []


def test_match_sets_fallthrough_for_later_cases():
    assert collected_cases('a', ['a', 'b', 'c']) == ['a', 'b', 'c']


def test_default_case_always_matches():
    assert collected_cases('z', ['a', None]) == [None]


def test_default_case_after_match_keeps_falling_through():
    assert collected_cases('a', ['a', None]) == ['a', None]


def test_match_accepts_multiple_values():
    switch = Switch('b')
    match = next(iter(switch))

    assert match('a', 'b') is True
    assert switch.fall is True


def test_no_argument_case_matches_immediately():
    switch = Switch('anything')
    match = next(iter(switch))

    assert match() is True


def test_match_is_false_before_any_hit():
    switch = Switch('b')
    match = next(iter(switch))

    assert match('a') is False
    assert switch.fall is False
